node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Re-check compatible_with_json and full product details
const product = db.prepare(\"SELECT compatible_with_json, description, specs_json FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('compatible_with_json:', product.compatible_with_json);
console.log('specs_json:', product.specs_json);
console.log('description:', product.description);

// Check if there's any table that might store compatibility info
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table' AND name LIKE '%compat%'\").all();
console.log('Compatibility tables:', JSON.stringify(tables));

// Search for iPhone 15 in products
const iphone = db.prepare(\"SELECT product_id, name FROM products WHERE name LIKE '%iPhone 15%'\").all();
console.log('iPhone 15 products:', JSON.stringify(iphone, null, 2));
"

